}
function workerConfirmed(enrollment: Record<string, unknown> | null): boolean {
  return enrollment?.enrolled === true && typeof enrollment.warning === "string";
}
async function startupWorker($: EngineInterface, sessionId: string, summaryCap: number): Promise<boolean> {
  if (!await workerDeclared($)) return true;
  const cwd = await $.session.cwd(), enrollment = await awaitWorkerEnrollment($, sessionId, cwd);
  if (workerConfirmed(enrollment)) { $.ui.log(`[lcm] ${enrollment!.warning}`); return true; }
  $.ui.log(`[lcm] worker mode refused: ${enrollment?.reason ?? "command-hook enrollment could not be confirmed"}; retrying`);
  void retryWorkerEnrollment($, sessionId, cwd, summaryCap).catch(error => { $.ui.log(`[lcm] worker enrollment retry stopped: ${String(error)}`); });
  return false;
}
function probeSessionDaemon($: EngineInterface): void {
  void readHostEnv($).then(({ port }) => {
    const startedAt = Date.now();
    return fetchDaemon($, `http://127.0.0.1:${port}/health`, undefined, HEALTH_PROBE_TIMEOUT_MS).then(() => undefined,
      async (error: unknown) => {
        if (isDaemonUnreachableError(error, startedAt)) await startDaemon($);
        else reportBusyDaemon($);
      });
  });
}
function registerSessionStart(on: On, summaryCap: number): void {
  on("session.start", async ($, e, next) => {
    const sessionId = await $.session.id();
    const mayServe = await startupWorker($, sessionId, summaryCap);
    await claimSession($, sessionId, "session.start");
    await flushHookObservations($, sessionId);
    probeSessionDaemon($);
    // The housekeeping the SessionStart command hook awaited. Nothing reads its result,
    // and the session has no reason to wait for a prune.
    void $.session.cwd().then(cwd => postDaemon($, "/session-scavenge", { cwd }));
    // Catch-up sweep for conversations of the same project a prior session left
    // uncompacted (it ended without SessionEnd). The daemon selects, caps and
    // fires the actual compaction requests; this call only triggers it.
    void $.session.cwd().then(cwd => postDaemon($, "/session-start-compact", { cwd, session_id: sessionId }));
    if (mayServe) startSummaryPoller($, summaryCap);
    return next(e);
  });
}

type RestoreResponse = {
  context?: string;
  insights?: { content: string; confidence?: number; tags: string[] }[];
};

/** The text the SessionStart command hook printed: the daemon's context, plus its insights. */
function restoreBlockText(body: Record<string, unknown> | null): string {
  const result = (body ?? {}) as RestoreResponse;
  const context = result.context ?? "";
  const insights = result.insights ?? [];
  if (insights.length === 0) return context;
  const seen = new Set<string>();
  const lines = insights.filter((i) => !seen.has(i.content) && seen.add(i.content))
    .map((i) => `- ${i.content}${typeof i.confidence === "number" ? ` (confidence: ${i.confidence})` : ""}`).join("\n");
  return `${context}\n<learned-insights source="passive-capture">\n`
    + `Recent learnings from your previous sessions:\n${lines}\n</learned-insights>`;
}

/**
 * `prompt.context` replaces the SessionStart command hook's stdout. It fires once per
 * conversation and again after compaction and `/clear` — the three moments the command
 * hook ran — but carries no reason for firing, so the daemon decides which content to
 * return from the mark `/compact` left for this session.
 */
function registerRestoreContext(on: On): void {
  on("prompt.context", async ($, e, next) => {
    const { blocks } = await next(e);
    const [session_id, cwd] = await Promise.all([$.session.id(), $.session.cwd()]);
    const outcome = await postDaemonOutcome($, "/restore", { session_id, cwd });
    const restored = outcome.body;
    const text = restoreBlockText(restored);
    noteHook(session_id, "prompt.context", "restore", "delivery", ...delivery(outcome));
    if (restored) noteHook(session_id, "prompt.context", "restore", "execution", "completed",
      text.trim() ? "context" : "no-context");
    if (!text.trim()) return { blocks };
    return { blocks: [...blocks, { name: "lcm", text }] };
  });
}

/**
 * The learning instruction goes into the system prompt once, cached for the session,
 * instead of riding on every prompt as the command hook's stdout did.
 */
function registerLearningInstruction(on: On): void {
  on("prompt.section", { name: "memory" }, async ($, e, next) => {
    const section = await next(e);
    noteHook(await $.session.id(), "prompt.section", "instruction", "execution", "completed");
    return { text: `${section.text ?? ""}\n\n${LEARNING_INSTRUCTION}` };
  });
}

/** Memory hits ride as hidden context on the prompt; the user never sees them. */
function registerPromptSearch(on: On): void {
  on("prompt.submit", async ($, e, next) => {
    if (!e.text.trim()) {
      noteHook(await $.session.id(), "prompt.submit", "search", "execution", "skipped", "empty-prompt");
      return next(e);
    }
    const [result, search] = await Promise.all([
      next(e),
      Promise.all([$.session.id(), $.session.cwd()]).then(([session_id, cwd]) =>
        postDaemonOutcome($, "/prompt-search", {
          query: e.text, cwd, session_id,
          learningInstructionBytes: 0, // the instruction lives in prompt.section now, not in this budget
          recordEvents: true,
          format: "context",
        })),
    ]);
    const sessionId = await $.session.id();
    noteHook(sessionId, "prompt.submit", "search", "delivery", ...delivery(search));
    if (search.body) noteHook(sessionId, "prompt.submit", "search", "execution", "completed",
      typeof search.body.context === "string" ? "context" : "no-context");
    if (result.drop !== undefined) return result;
    const context = typeof search.body?.context === "string" ? search.body.context : null;
    if (!context) return result;
    return { ...result, context: [...(result.context ?? []), context] };
  });
}

/**
 * The session's transcript is ingested incrementally as turns end, so memory does not wait
 * for SessionEnd. The daemon derives the transcript path from session id and cwd.
 */
function registerTurnIngest(on: On): void {
  on("turn.complete", async ($, e, next) => {
    const result = await next(e);
    const session_id = await $.session.id();
    const now = Date.now();
    if (now - lastIngestAt < INGEST_INTERVAL_MS) {
      noteHook(session_id, "turn.complete", "capture", "execution", "deferred", "throttled");
      await flushHookObservations($, session_id);
      return result;
    }
    lastIngestAt = now;
    const cwd = await $.session.cwd();
    const captured = await postDaemonOutcome($, "/ingest", { session_id, cwd });
    noteHook(session_id, "turn.complete", "capture", "delivery", ...delivery(captured));
    if (captured.body) noteHook(session_id, "turn.complete", "capture", "execution", "completed");
    const promoted = await postDaemonOutcome($, "/promote-events", { cwd });
    noteHook(session_id, "turn.complete", "promote-events", "delivery", ...delivery(promoted));
    await flushHookObservations($, session_id);
    return result;
  });
}

/** The same body the PostToolUse command hook reads on stdin, so both paths write one row shape. */
function toolEventPayload(
  event: Record<string, unknown>, result: { isError?: boolean; result?: unknown; text?: string },
  session_id: string, cwd: string,
): Record<string, unknown> {
  const { tool, tool_use_id, ...tool_input } = event as { tool: string; tool_use_id: string } & Record<string, unknown>;
  const failed = result.isError === true;
  return {
    session_id, cwd, tool_use_id, harness: "claude-function",
    tool_name: tool,
    tool_input,
    tool_response: result.result,
    tool_output: failed ? { isError: true } : undefined,
    hook_event_name: failed ? "PostToolUseFailure" : "PostToolUse",
    error: failed ? result.text : undefined,
  };
}

/** One hook replaces both PostToolUse and PostToolUseFailure; the daemon writes the rows. */
function registerToolCapture(on: On): void {
  on("tool.call", async ($, e, next) => {
    const captured = CAPTURED_TOOLS.has(e.tool) || e.tool.startsWith("mcp__");
    if (!captured) {
      const result = await next(e);
      noteHook(await $.session.id(), "tool.call", "tool-capture", "execution", "skipped", "unmatched-tool");
      return result;
    }

    const result = await next(e);
    if (result.deny !== undefined) {
      noteHook(await $.session.id(), "tool.call", "tool-capture", "execution", "skipped", "denied");
      return result;
    }

    const [session_id, cwd] = await Promise.all([$.session.id(), $.session.cwd()]);
    const recorded = await postDaemonOutcome($, "/tool-event", toolEventPayload(e, result, session_id, cwd));
    noteHook(session_id, "tool.call", "tool-capture", "delivery", ...delivery(recorded));
    if (recorded.body) noteHook(session_id, "tool.call", "tool-capture", "execution", "completed",
      typeof recorded.body.recorded === "number" && recorded.body.recorded > 0 ? "events" : "no-match");
    return result;
  });
}

export const register: Register = (on, options) => {
  const summaryCap = normalizedSummaryCap(options.sessionSummarizerMaxOutputTokens);
  const shadow = options.compactionShadow === true ? shadowSessions : undefined;
  registerSessionStart(on, summaryCap);
  registerSessionClaim(on, shadow);
  registerSessionEnd(on, shadow);
  registerRestoreContext(on);
  registerLearningInstruction(on);
  registerPromptSearch(on);
  registerTurnIngest(on);
  registerToolCapture(on);
  if (options.compactionShadow === true) registerCompactionShadow(on, summaryCap);
};
const shadowSessions = new ShadowSessionState();
function shadowTransport($: EngineInterface): ShadowTransport {
  return { post: (route, body, deadline) => postShadow($, { route, body }, deadline), observe: (status, reason, sessionId) => noteHook(sessionId ?? "unknown", "session.compact", "shadow", "execution", status, reason) };
}
async function postShadow($: EngineInterface, { route, body }: { route: string; body: unknown }, deadline?: ShadowDeadline): Promise<PostOutcome> {
  if (!deadline) return postDaemonOutcome($, route, body);
  deadline.check();
  const { port, token } = await readHostEnv($);
  deadline.check();
  const response = await $.http.fetch(`http://127.0.0.1:${port}${route}`, {
    method: "POST", headers: { "content-type": "application/json", ...(token ? { authorization: `Bearer ${token}` } : {}) }, body: JSON.stringify(body),
  });
  deadline.check();
  return { body: response.ok ? JSON.parse(response.text) as Record<string, unknown> : null, connectionFailed: false, httpStatus: response.status };
}
function shadowEngine($: EngineInterface): ShadowEngine {
  return { clock: { after: (ms, callback) => $.clock.after(ms, callback) }, env: { get: () => $.env.get("LCM_SUMMARIZE_WORKER") }, session: { id: () => $.session.id(), cwd: () => $.session.cwd(), model: () => $.session.model() },
    model: { fork: request => $.model.fork(request), complete: (request, options) => $.model.complete(request, options) } };
}
function registerCompactionShadow(on: On, cap: number): void {
  on("session.append", async ($, event, next) => {
    let sessionId: string;
    try { sessionId = await $.session.id(); }
    catch { noteHook("unknown", "session.append", "shadow", "execution", "unavailable", "identity"); return next(event); }
    const owner = event.agentId === undefined ? shadowSessions.beginAppend(sessionId, event.door) : undefined;
    const result = await next(event);
    settledShadowAppend(owner, result);
    return result;
  });
  on("session.compact", async ($, event, next) => {
    return runCompactionShadow(shadowEngine($), { event, next, state: shadowSessions, cap, signal: next.signal }, shadowTransport($));
  });
}
function settledShadowAppend(owner: ShadowAppend | undefined, result: import("claude-code").EventResult<"session.append">): void {
  if (!owner || result.deny !== undefined) return;
  if (result.message.role === undefined) return;
  const text = result.message.content.filter(block => block.type === "text").map(block => block.text).join("\n");
  shadowSessions.storedAppend(owner, { uuid: result.uuid, text });
}
function normalizedSummaryCap(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return DEFAULT_SUMMARY_OUTPUT_CAP;
  return Math.min(Number.MAX_SAFE_INTEGER, Math.max(0, Math.floor(value)));
}

